/* 日々: compact working views. All figures come from the current ledger. */
function utilityMonth(){return period();}
function utilityHeading(title,{monthly:withMonth=false,action='',label='',back=true}={}){
  return `<header class="utility-heading ${withMonth?'has-month':''} ${withMonth&&action?'has-month-action':''}"><div class="utility-title">${back?'<button class="utility-back" data-action="app-back" data-fallback="more" aria-label="返回更多"><span class="month-chevron previous" aria-hidden="true"></span></button>':''}<h1>${title}</h1></div>${action?`<button class="utility-add" data-action="${action}">${icon('plus')}<span>${label}</span></button>`:''}${withMonth?period():''}</header>`;
}
function utilitySection(title,aside=''){return `<div class="utility-section-head"><h2>${title}</h2>${aside?`<span>${aside}</span>`:''}</div>`;}
function utilitySigned(value){return `${value>0?'+':value<0?'−':''}${money(Math.abs(value))}`;}
function utilityPercent(value,total){return total>0?value/total*100:0;}
function utilityMeter(value,total){return Math.min(100,Math.max(0,utilityPercent(value,total)));}
function utilityColor(row){return categoryByName(row.name)?.color||ledgerIconColors[row.name]||'#887465';}
function utilityGlyph(name,color){return `<span class="utility-glyph" style="--glyph:${color||'#45634f'}">${icon(name)}</span>`;}
function utilityFlowRail(t){
  const sum=Math.max(0,t.income)+Math.abs(t.expense);
  return `<span class="report-flow-rail" role="img" aria-label="收入 ${money(t.income)}，${t.expense<0?'淨退款':'支出'} ${money(Math.abs(t.expense))}"><i class="income" style="width:${utilityMeter(t.income,sum)}%"></i><i class="${t.expense<0?'refund':'expense'}" style="width:${utilityMeter(Math.abs(t.expense),sum)}%"></i></span>`;
}
function reportRing(rows){
  const total=rows.reduce((sum,row)=>sum+Math.max(0,row.amount),0),radius=70,circumference=2*Math.PI*radius;
  let offset=0;
  const segments=rows.filter(row=>row.amount>0).map(row=>{
    const length=row.amount/total*circumference,gap=Math.min(3,length*.15),start=offset+gap/2;offset+=length;
    return `<circle class="report-ring-segment" cx="88" cy="88" r="${radius}" fill="none" stroke="${utilityColor(row)}" stroke-width="17" stroke-dasharray="${length-gap} ${circumference-length+gap}" stroke-dashoffset="${-start}" transform="rotate(-90 88 88)"></circle>`;
  }).join('');
  return `<svg viewBox="0 0 176 176" role="img" aria-label="各分類正支出占比"><circle cx="88" cy="88" r="70" fill="none" stroke="#e7e0d3" stroke-width="17"/>${segments}</svg>`;
}
function previousMonth(value=month){const [y,m]=value.split('-').map(Number);return new Date(Date.UTC(y,m-2,1)).toISOString().slice(0,7);}
function monthDividend(value=month){return monthly(value).filter(t=>t.type==='income'&&t.dividend).reduce((sum,t)=>sum+t.amount,0);}
function expenseByCategory(value){const facts=new Map();for(const t of monthly(value))if(['expense','refund'].includes(t.type)){const row=facts.get(t.category)||{name:t.category,amount:0,count:0};row.amount+=t.type==='refund'?-t.amount:t.amount;row.count++;facts.set(t.category,row);}return facts;}
function reportComparison(){
 const previous=previousMonth(),current=totals(),before=totals(previous),nowRows=expenseByCategory(month),oldRows=expenseByCategory(previous),names=new Set([...nowRows.keys(),...oldRows.keys()]);
 const rows=[...names].map(name=>({name,amount:nowRows.get(name)?.amount||0,before:oldRows.get(name)?.amount||0,count:nowRows.get(name)?.count||0,previousCount:oldRows.get(name)?.count||0})).map(r=>({...r,delta:r.amount-r.before})).sort((a,b)=>Math.abs(b.delta)-Math.abs(a.delta)||b.amount-a.amount);
 return {previous,current,before,rows,delta:current.expense-before.expense,hasCurrent:nowRows.size>0,hasPrevious:monthly(previous).some(t=>['expense','refund'].includes(t.type))};
}
function emptyAction(title,action,label,route=false){return `<div class="designed-empty"><span>${icon('ledger')}</span><p>${esc(title)}</p>${action?`<button class="empty-action" ${route?'data-route':'data-action'}="${action}">${esc(label)}</button>`:''}</div>`;}
function reports(){
 const f=reportComparison(),t=f.current,net=t.income-t.expense,max=Math.max(1,...f.rows.map(r=>Math.abs(r.delta))),driver=f.rows.find(r=>r.delta!==0);
 return `<div class="utility-page reports-page">${utilityHeading('財務報表',{monthly:true})}<section class="report-summary"><div class="report-net"><span>本月結餘</span><div>${currencyFigure(net,{tone:net<0?'negative':'positive'})}</div>${t.income>0?`<b class="report-saving">結餘率 ${Math.round(net/t.income*100)}%</b>`:''}</div><div class="report-flow-values"><button data-action="home-income"><span><i class="income-dot"></i>收入</span><strong class="positive">${money(t.income)}</strong></button><button data-action="home-expense"><span><i class="expense-dot"></i>${t.expense<0?'淨退款':'支出'}</span><strong class="${t.expense<0?'positive':'expense-amount'}">${money(Math.abs(t.expense))}</strong></button></div>${utilityFlowRail(t)}</section>
 <section class="report-change ${!f.hasCurrent||!f.hasPrevious?'no-comparison':f.delta>0?'spending-up':'spending-down'}" aria-label="支出月份比較"><div><span>${month===TODAY.slice(0,7)?'至 '+Number(TODAY.slice(8))+' 日支出':'本月支出'} · 較 ${Number(f.previous.slice(5))} 月</span><strong>${!f.hasCurrent?'本月尚無支出':!f.hasPrevious?'尚無比較基準':f.delta===0?'持平':`${f.delta>0?'增加':'減少'} ${money(Math.abs(f.delta))}`}</strong></div>${f.hasCurrent&&f.hasPrevious&&driver?`<p>主要變動 <b>${esc(driver.name)}</b><span class="${driver.delta>0?'negative':'positive'}">${utilitySigned(driver.delta)}</span></p>`:''}</section>
 <section class="utility-section report-drivers">${utilitySection(f.hasPrevious?'分類變化':'分類支出',f.hasPrevious?'較上月增減':'本月淨額')}${f.hasCurrent?'<div class="report-change-key"><span>減少</span><span>增加</span></div>':''}${f.hasCurrent?f.rows.map(r=>`<button class="report-driver" data-action="category" data-type="expense" data-category="${esc(r.name)}" aria-label="${esc(r.name)}，本月 ${money(r.amount)}，上月 ${money(r.before)}，差額 ${utilitySigned(r.delta)}"><span class="report-driver-name"><span class="driver-symbol" style="--glyph:${utilityColor(r)}">${journalIcon({type:'expense',category:r.name})}</span><strong>${esc(r.name)}</strong></span><span class="report-driver-plot" aria-hidden="true"><i class="${r.delta>0?'up':'down'}" style="width:${Math.abs(r.delta)/max*50}%"></i></span><span class="report-driver-value"><strong class="${amountTextClass(r.amount)} ${r.amount<0?'positive':'expense-amount'}">${r.amount<0?'淨退款 ':''}${money(Math.abs(r.amount))}</strong><small class="${r.delta>0?'negative':r.delta<0?'positive':''}">${!f.hasPrevious?r.count+' 筆':r.delta===0?'與上月相同':utilitySigned(r.delta)}</small></span></button>`).join(''):emptyAction('這個月還沒有支出紀錄','entry','記下第一筆')}</section></div>`;
}
function categoryOverview(){
 return `<div class="utility-page categories-page">${utilityHeading('分類管理')}${['expense','income'].map(type=>{
 const active=managedCategories(type),inactive=managedCategories(type,true).filter(c=>c.active===false);
 const tile=c=>`<button class="category-tile ${c.active===false?'is-inactive':''}" data-action="category-edit" data-id="${esc(c.id)}" style="--category:${c.color}" aria-label="編輯${esc(c.name)}${c.active===false?'，已停用':''}"><span class="category-symbol">${categorySymbol(c)}</span><strong>${esc(c.name)}</strong>${c.active===false?'<span class="category-disabled-label">已停用</span>':''}</button>`;
 return `<section class="category-family">${utilitySection(type==='expense'?'支出分類':'收入分類')}<div class="category-collection">${active.map(tile).join('')}<button class="category-tile category-add" data-action="category-new" data-type="${type}"><span class="category-symbol">${icon('plus')}</span><strong>新增分類</strong></button></div>${inactive.length?`<div class="category-inactive"><h3>已停用</h3><div class="category-collection">${inactive.map(tile).join('')}</div></div>`:''}</section>`;
 }).join('')}</div>`;
}
function portfolioFacts(){
  const value=investmentTotal(),cost=state.holdings.reduce((sum,h)=>sum+h.cost,0),dividends=state.holdings.reduce((sum,h)=>sum+(Number(h.dividend)||0),0)+activeTx().filter(t=>t.dividend&&t.type==='income').reduce((sum,t)=>sum+t.amount,0);
  return {value,cost,profit:value-cost,rate:cost>0?(value-cost)/cost*100:null,dividends,realized:investmentPositions().reduce((sum,h)=>sum+h.realized,0)};
}
function valuationBars(cost,value){
  const max=Math.max(cost,value,1),costWidth=utilityMeter(cost,max)*3.12,valueWidth=utilityMeter(value,max)*3.12;
  return `<figure class="valuation-bars" aria-label="成本 ${money(cost)}，市值 ${money(value)}"><div class="valuation-labels"><span><i class="cost-key"></i>成本<strong>${money(cost)}</strong></span><span><i class="market-key"></i>市值<strong>${money(value)}</strong></span></div><svg viewBox="0 0 320 38" role="img" aria-label="成本與市值比較"><rect class="valuation-track" x="4" y="5" width="312" height="9" rx="4.5"/><rect class="valuation-cost" x="4" y="5" width="${costWidth}" height="9" rx="4.5"/><rect class="valuation-track" x="4" y="24" width="312" height="9" rx="4.5"/><rect class="valuation-market" x="4" y="24" width="${valueWidth}" height="9" rx="4.5"/></svg></figure>`;
}
function holdingValueWidth(value,max){return value>0?8+utilityMeter(value,max)*.92:0;}
function investments(){
 const f=portfolioFacts(),dividendRows=recent(monthly().filter(t=>t.type==='income'&&t.dividend)),profits=state.holdings.map(h=>h.qty*h.price-h.cost),currentDividend=monthDividend();
 return `<div class="utility-page investments-page">${utilityHeading('投資與股息')}<section class="portfolio-summary"><div class="portfolio-eyebrow"><span>未實現損益</span><button class="quote-manage" data-action="quotes-manage">${portfolioQuoteStatus()}</button></div><div class="portfolio-total">${currencyFigure(f.profit,{signed:true,tone:f.profit<0?'negative':'positive'})}<span class="portfolio-return ${f.profit<0?'negative':'positive'}">${f.rate===null?'—':`${f.rate>0?'+':''}${f.rate.toFixed(1)}%`}</span></div><div class="portfolio-basis"><div><span>持股市值</span><strong>${money(f.value)}</strong></div><div><span>投入成本</span><strong>${money(f.cost)}</strong></div><div><span>已實現損益</span><strong class="${f.realized<0?'negative':'positive'}">${utilitySigned(f.realized)}</strong></div></div></section>
 <section class="portfolio-income"><div class="portfolio-dividend-head"><h2>股息入帳</h2>${period()}</div><div class="dividend-month"><div><span>本月股息</span><strong>${money(currentDividend)}</strong></div><button class="utility-add" data-action="dividend">${icon('plus')}<span>記股息</span></button></div><div class="dividend-cumulative"><span>累計股息</span><strong>${money(f.dividends)}</strong></div></section>
 <section class="utility-section">${utilitySection('持股損益',chartScaleControl('investment'))}<div class="portfolio-holdings" data-scale="${chartScale('investment')}">${state.holdings.map(h=>{const value=h.qty*h.price,profit=value-h.cost,rate=h.cost>0?profit/h.cost*100:null;return `<button class="portfolio-holding ${profit<0?'is-loss':''}" data-action="holding" data-id="${esc(h.id)}" aria-label="${esc(h.id+' '+h.name)}，損益 ${utilitySigned(profit)}，市值 ${money(value)}"><span class="holding-identity"><strong>${esc(h.name)}</strong><small>${esc(h.id)}<span>${rate===null?'—':`${rate>0?'+':''}${rate.toFixed(1)}%`}</span></small></span><span class="holding-profit-plot" aria-hidden="true"><i class="${profit===0?'flat':profit<0?'loss':'gain'}" style="width:${investmentBarWidth(profit,profits)}%"></i></span><span class="holding-numbers"><strong class="${amountTextClass(profit)} ${profit<0?'negative':'positive'}">${utilitySigned(profit)}</strong><small>市值 ${money(value)}</small></span></button>`;}).join('')||emptyAction('目前沒有持股','','')}</div></section>
 ${dividendRows.length?`<section class="utility-section portfolio-dividends">${utilitySection('本月入帳紀錄',`${dividendRows.length} 筆`)}${dividendRows.map(txRow).join('')}</section>`:''}</div>`;
}
function budgetFacts(b){
  const used=spent(b.category),remaining=b.limit-used,rate=b.limit>0?used/b.limit*100:null;
  return {used,remaining,rate,over:used>b.limit,width:b.limit>0?utilityMeter(used,b.limit):used>0?100:0};
}
function budgetRate(f){return f.rate===null?'未設定':`${Math.round(f.rate)}%`;}
function budgetRuler(f){
  const width=f.width*3.12,point=4+width,label=budgetRate(f),halfLabel=Math.max(25,[...label].reduce((sum,c)=>sum+(c.charCodeAt(0)>255?14:8),0)/2+4),labelX=Math.max(halfLabel,Math.min(320-halfLabel,point));
  return `<svg class="budget-ruler ${f.over?'is-over':''}" viewBox="0 0 320 51" role="img" aria-label="預算已使用 ${label}"><rect class="budget-track" x="4" y="2" width="312" height="12" rx="6"/><rect class="budget-fill" x="4" y="2" width="${width}" height="12" rx="6"/><path class="budget-pointer" d="M${point-3} 20L${point} 16L${point+3} 20Z"/><text class="budget-end" x="4" y="31">0</text><text class="budget-end" x="316" y="31" text-anchor="end">100</text><text class="budget-rate" x="${labelX}" y="47" text-anchor="middle">${label}</text></svg>`;
}
function budgets(){
 const total=state.budgets.find(b=>b.id==='total'),f=total?budgetFacts(total):null,items=state.budgets.filter(b=>b.id!=='total').map(b=>({...b,facts:budgetFacts(b)})).sort((a,b)=>Number(b.facts.over)-Number(a.facts.over)||(b.facts.rate??-1)-(a.facts.rate??-1));
 return `<div class="utility-page budgets-page">${utilityHeading('預算管理',{monthly:true})}${f?`<section class="budget-overview ${f.over?'is-over':''}"><div class="budget-overview-top"><div class="utility-key-value"><span>${f.over?'本月超支':'本月剩餘'}</span>${currencyFigure(Math.abs(f.remaining),{tone:f.over?'negative':'positive'})}</div><button class="budget-limit-button" data-action="edit-budget" data-id="total" aria-label="調整總預算 ${money(total.limit)}"><span>總預算 ${icon('edit')}</span><strong>${money(total.limit)}</strong></button></div>${budgetRuler(f)}<div class="budget-used"><span class="${f.used<0?'positive':'expense-amount'}">已用 ${money(f.used)}</span></div></section>`:''}<section class="utility-section">${utilitySection('分類額度')}<div class="budget-collection">${items.map(b=>{const s=b.facts;return `<article class="budget-allocation ${s.over?'is-over':s.rate>=80?'is-near':''}" style="--category:${utilityColor({name:b.category})}"><button class="budget-category" data-action="category" data-type="expense" data-category="${esc(b.category)}" aria-label="${esc(b.category)}，已用 ${money(s.used)}，額度 ${money(b.limit)}，${s.over?'超支':'剩餘'} ${money(Math.abs(s.remaining))}"><span class="budget-category-icon">${journalIcon({type:'expense',category:b.category})}</span><span class="budget-category-copy"><span class="budget-category-title"><strong>${esc(b.category)}</strong><span class="budget-remaining ${s.over?'negative':''}">${s.over?'超支':'剩餘'} <b>${money(Math.abs(s.remaining))}</b></span></span><span class="budget-track-row"><span class="utility-track"><i style="width:${s.width}%"></i></span><small>${b.limit?money(b.limit):'未設定'}</small></span></span></button><button class="budget-edit" data-action="edit-budget" data-id="${esc(b.id)}" aria-label="調整${esc(b.category)}預算">${icon('edit')}</button></article>`;}).join('')||emptyAction('尚未設定分類額度','','')}</div></section></div>`;
}
function recurringPosting(r){return activeTx().find(t=>t.recurring===r.id&&t.date.startsWith(month));}
function recurringRow(r,status){
 const posting=status==='confirmed'?recurringPosting(r):null,date=posting?.date||dueDate(r),pending=['pending','upcoming'].includes(status),amount=posting?.amount??r.amount,action=pending?'confirm-recurring':posting?'recurring-posted':'recurring-manage';
 return `<article class="routine-item ${status}" data-recurring-id="${esc(r.id)}"><button class="routine-open" data-action="${action}" data-id="${esc(r.id)}" aria-label="${esc(r.name)}，${money(amount)}，${status==='pending'?'確認入帳':status==='upcoming'?'提前確認入帳':posting?'查看入帳紀錄':'管理定期交易'}"><span class="routine-date"><small>${Number(date.slice(5,7))} 月</small><strong>${Number(date.slice(8))}</strong></span><span class="routine-copy"><strong>${esc(r.name)}</strong><small>${esc(account(posting?.account||r.account)?.name||'帳戶')}</small></span><span class="routine-value"><strong>${money(amount)}</strong><small class="${status==='pending'?'is-due':''}">${{pending:'確認入帳',upcoming:'即將到期',confirmed:'已入帳',paused:'已暫停'}[status]}</small></span></button></article>`;
}
function recurring(){
 const all=[...state.recurring].sort((a,b)=>a.day-b.day),{due,upcoming,title}=recurringReminderCopy(),confirmed=all.filter(r=>recurringConfirmed(r)),paused=all.filter(r=>!r.active&&!recurringConfirmed(r)),next=upcoming[0];
 return `<div class="utility-page recurring-page">${utilityHeading('定期交易',{monthly:true})}<section class="routine-summary ${due.length?'has-due':''}"><div><span>${title}</span>${due.length?currencyFigure(due.reduce((sum,r)=>sum+r.amount,0)):`<strong class="routine-next">${next?esc(next.name):!all.length?'安排每月支出':'本期已整理完成'}</strong>`}${!due.length&&next?`<small>下一筆 ${Number(dueDate(next).slice(5,7))} / ${Number(dueDate(next).slice(8))} · ${nt(next.amount)}</small>`:''}</div><button class="utility-add" data-action="recurring-new">${icon('plus')}<span>新增</span></button></section><div class="routine-management"><button data-action="recurring-manage">${icon('settings')}管理固定項目</button></div>${[['pending','待確認',due],['upcoming','即將到期',upcoming],['confirmed','已入帳',confirmed],['paused','已暫停',paused]].filter(([, ,rows])=>rows.length).map(([status,title,rows])=>`<section class="utility-section routine-section ${status}">${utilitySection(title,`${rows.length} 筆`)}<div class="routine-list">${rows.map(r=>recurringRow(r,status)).join('')}</div></section>`).join('')||emptyAction('加入房租、訂閱或其他固定支出','recurring-new','新增定期交易')}</div>`;
}
function settings(){
  return `<div class="utility-page settings-page">${utilityHeading('設定與資料')}<section class="utility-section">${utilitySection('日常偏好')}<div class="settings-preferences"><div class="preference-row">${utilityGlyph('eye','#4c7155')}<div><h3>隱藏摘要金額</h3></div><button class="utility-toggle ${state.privacy?'on':''}" role="switch" aria-checked="${state.privacy}" aria-label="隱藏摘要金額" data-action="privacy"><i aria-hidden="true"></i></button></div><div class="preference-row">${utilityGlyph('accounts','#8d6a41')}<div><h3>記帳幣別</h3></div><strong class="preference-value">TWD</strong></div></div></section><section class="utility-section">${utilitySection('匯出帳本')}<div class="settings-export"><div class="export-period"><span>選擇月份</span>${utilityMonth()}</div><button class="export-action" data-action="export"><span class="export-file">CSV</span><span><strong>下載收支紀錄</strong><small>${labelMonth()} · ${monthly().length} 筆紀錄</small></span>${icon('export')}</button><button class="export-action" data-action="download-demo"><span class="export-file">JSON</span><span><strong>下載完整帳本</strong></span>${icon('export')}</button></div></section>${state.undoDelete?'<button class="settings-undo" data-action="undo-delete">復原上次刪除</button>':''}<button class="settings-reset" data-action="reset"><span><strong>重設演示資料</strong></span>${icon('recurring')}</button></div>`;
}
function more(){
 const r=recurringReminderCopy(),items=[['reports','財務報表','#315d47'],['investments','投資與股息','#567b83'],['budgets','預算管理','#927243'],['recurring','定期交易','#8b403b'],['categories','分類管理','#9a6849'],['settings','設定與資料','#746785']];
 return `<div class="utility-page more-page">${utilityHeading('更多',{back:false})}<button class="more-reminder ${r.due.length?'has-pending':''}" data-route="recurring">${utilityGlyph('calendar',r.due.length?'#8b403b':'#315d47')}<span><strong>${r.title}</strong><small>${r.detail||labelMonth()}</small></span></button><div class="more-tool-grid">${items.map(([route,title,color])=>`<button class="more-tool" data-route="${route}" style="--tool-color:${color}">${utilityGlyph(route,color)}<strong>${title}</strong></button>`).join('')}</div></div>`;
}
